    "clinicalCase": "Paciente de 40 anos, sexo masculino, cerca de 70 Kg, levado ao serviço de Urgência e Emergência por equipe dos Bombeiros, com relato de ter sofrido queda da laje de sua casa (cerca de 3 metros de altura) há 30 minutos. Familiar que o acompanhava relata que o paciente não possui comorbidades e não faz uso de medicações. À admissão, o paciente apresentava frequência cardíaca = 90 bpm, pressão arterial = 120 x 80 mmHg, saturação de oxigênio = 100% com oxigênio suplementar sob máscara. Conversava e respondia às perguntas do médico sem dificuldades e com frases ordenadas, mobilizava os 4 membros espontaneamente e havia abertura ocular espontânea. O paciente relata que se lembra da queda e que “bateu a cabeça no chão”. Realizou avaliação primária e secundária adequadas. Havia discreta equimose retroauricular e ferida corto-contusa de 3 cm, superficial, em região parietal direita. Exame físico do tórax e abdome sem alterações. Na avaliação secundária foi realizada tomografia computadorizada (TC) de crânio, pescoço, tórax e abdome. TC crânio sem contraste: discreto hematoma extradural à direita. TC pescoço, incluindo coluna cervical, com contraste venoso: sem alterações. TC de tórax e abdome com contraste venoso: sem alterações. Cerca de 2 horas após o exame de tomografia, o paciente apresentava-se com abertura ocular apenas ao estímulo doloroso e fala com palavras inapropriadas. Apresentou dois episódios de vômitos, FC = 62 bpm; PA = 180 x 110 mmHg. Pupila direita em midríase e hemiparesia esquerda. Foi realizada novamente a avaliação primária, sem outras alterações além das descritas. Com os dados apresentados, assinale a alternativa que contenha o diagnóstico, raciocínio e conduta corretos.",
