    "clinicalCase": "Um paciente do sexo masculino, de 3 anos de idade, é levado a serviço de emergência em decorrência de febre e exantema há 7 dias. Mãe relata que a febre é diária e chegou a 39 oC. O exantema surgiu há 2 dias. O paciente já passou por outros serviços de emergência sem conseguir fechar diagnóstico. Nega doenças prévias. Desenvolvimento normal para a idade. Ao exame, mostra- se em regular estado geral, descorado 1+/4+, febril (38,5 oC), acianótico e hidratado. Presença de exantema maculopapular e edema e hiperemia nas mãos e pés, rash em tronco e períneo, bem como de hiperemia conjuntival bilateral. Cavidade oral revela fissuras em lábios. Há linfonodomegalia cervical, unilateral direita, com 2 cm de diâmetro. Aparelho cardiovascular, respiratório e abdome sem anormalidades. Considerando a história acima descrita, assinale a alternativa que contém o tratamento indicado.",
