    "clinicalCase": "Um homem de 52 anos de idade procura atendimento médico em nível ambulatorial após 7 dias de uma internação hospitalar de 72 horas para correção de uma hérnia inguinal, na qual permaneceu 24 horas com sonda vesical de demora. O paciente encontra-se em bom estado de saúde, queixando-se de leve dor no local da cirurgia e de disúria, iniciada há 3 dias, além de polaciúria. Ao exame, a ferida operatória encontra-se limpa e apresenta dor à palpação profunda do hipogástrio. No mais, o exame físico é completamente normal. Possui comorbidades, pois é diabético e portador de epilepsia em uso de topiramato para essa última condição. O médico assistente solicitou uma urocultura, cujo resultado segue abaixo. Material da amostra Urina Resultado da cultura Positiva 100 000 UFC E. coli Concentração Antibiograma Inibitória Mínima Amicacina Resistente ≥ 32 Ampicilina Resistente ≥ 32 Ampicilina/Sulbactan Resistente ≥ 32 Cefepime Resistente ≥ 64 Ceftazidima Resistente 16 Ceftriaxona Resistente ≥ 64 Cefoxitina Sensível ≤ 2 Cefuroxima Resistente ≥ 64 Ciprofloxacina Resistente ≥ 16 Ertapenem Sensível ≤ 0,5 Gentamicina Resistente ≥ 16 Imipenem Sensível ≤ 0,5 Piperacilina/Tazobactan Resistente ≥ 64 Sulfametoxazol/Trimetoprim Sensível ≤ 0,5 Nesse caso, a conduta do médico deve ser",
