    "clinicalCase": "Paciente do sexo masculino, 65 anos, foi atendido no serviço de urgência de um hospital com queixa de dor em flanco e fossa ilíaca esquerdos, com início há cerca de 48 horas e piora nas últimas 12 horas. Neste período, apresentou episódio febril de 38 oC, aferido em seu domicílio. Relatou apresentar divertículos do cólon há cerca de 12 anos, e que foi submetido a uma gastrectomia parcial há 1 ano por adenocarcinoma gástrico em antro, estágio IB. Apresentou relatório médico relativo a esse procedimento, no qual constava endoscopia digestiva alta com biópsia confirmando o diagnóstico histológico, tomografia computadorizada de abdome e tórax, que revelava doença diverticular em sigmoide, e colonoscopia confirmando doença diverticular em sigmoide. Ao exame físico, o paciente estava em bom estado geral, frequência cardíaca de 95 bpm, pressão arterial de 130 x 80 mmHg e temperatura axilar de 38,1 oC. O abdome estava flácido, mas doloroso à palpação profunda de flanco e fossa ilíaca esquerdos e hipogástrio. Hemograma revelou leucocitose de 16 000/mm3 (referência: 9 000 – 11 000/mm3) com 10% de bastões (referência: 0 – 5%). O paciente relatou estar preocupado pela possibilidade de ser um “retorno do câncer”. O exame complementar e explicação para confirmação do diagnóstico nesse momento é",
