    "clinicalCase": "Um homem de 57 anos de idade comparece ao ambulatório de clínica médica de hospital de média complexidade para avaliação diagnóstica de quadro de fraqueza, cansaço, adinamia e desequilíbrio nos membros inferiores (MMII). Segundo informa, seu estado geral era bom até 3 meses antes, quando passou a perceber fraqueza e adinamia. Pensou ser decorrente do hipotireoidismo, mas após reavaliação hormonal, sua endocrinologista informou-lhe que a tireoidite de Hashimoto estava bem controlada, não sendo necessário nenhum reajuste da dose de levotiroxina em uso crônico (125 mcg/dia). Como os sintomas persistiram, procurou facultativo que lhe solicitou um hemograma completo, cujo resultado revelou o seguinte padrão: hemoglobina: 7,6 g/dL (valor de referência: 13 a 16,5 g/dL); hematócrito: 26% (valor de referência: 40 a 52%); hemácias: 2,3 x 106/mcl (valor de referência: 4,5 a 6,0 x 106/mcl); volume corpuscular médio: 113 fl (valor de referência: 80 a 100 fl); leucócitos: 2 800/mcl (valor de referência: 6 000 a 10 000/mcl), com contagem diferencial normal; plaquetas: 86 000/mcl (valor de referência: 150 a 400 x 103/mcl). Ao exame físico procedido na consulta, o paciente encontra- se bastante pálido, ictérico (+/4+), normotenso, levemente taquicárdico (104 bpm) e hidratado; exame do aparelho cardiovascular revela apenas sopro sistólico pancardíaco, enquanto o exame do aparelho respiratório e do abdome é normal. Contudo, ao exame neurológico, é observada perda da propriocepção consciente e da sensibilidade vibratória nos MMII, sendo o reflexo cutâneo-plantar em extensão bilateral. Uma hematoscopia realizada durante o exame no ambulatório revela a presença de plurissegmentação dos neutrófilos. A etiologia mais provável da anemia do paciente em apreço é",
