    "clinicalCase": "Um lactente masculino, com 5 semanas de vida, chegou no pronto-socorro com história de vômitos em jato (sem bile) logo após as mamadas. A mãe relata que não está entendendo porque ele não está engordando. Nasceu com 3 500 g. Apesar dos vômitos, que tiveram início pouco depois do nascimento, ele demonstrava muita fome e sugava “com vontade” o leite materno, mas desde ontem está hipoativo, quase não urina e a boca está seca. O exame apresentou os seguintes resultados: P = 3 600 g, sinal da prega presente, mucosa oral seca, hipoativo, perfusão capilar em 4 segundos, massa semelhante a uma azeitona, discreta, firme, móvel, de 2 a 3 cm, palpável no fundo do lado direito do epigástrio. Sem outras anormalidades. Considerando os diagnósticos do lactente, qual conduta médica deve ser adotada?",
