    "clinicalCase": "Uma mulher de 38 anos de idade é admitida na enfermaria de cardiologia de hospital de alta complexidade, em função de quadro de dispneia progressiva, ortopneia e dispneia paroxística noturna. Segundo a paciente informa, seus sintomas anteriores iniciaram-se há cerca de 1 ano, tendo progredido ao longo do período. Procurou assistência médica em algumas ocasiões, sendo finalmente internada para realização de exames complementares e definição diagnóstica. Em sua história patológica pregressa, há relato de dois episódios de febre reumática na adolescência, num dos quais foi detectado um \"sopro no coração\". Fez uso de penicilina benzatina de forma mensal, mas irregular, até os 18 anos de idade. Nega outros dados relevantes de anamnese. Ao exame físico, paciente está em bom estado geral, em atitude ortopneica. Não há febre. PA = 120 x 70 mmHg; FC = 87 bpm. Ritmo cardíaco é irregular, em 2 tempos, com 1.a bulha hiperfonética e presença de sopro diastólico (2+/6+) em ponta, melhor audível em semi-decúbito lateral esquerdo; um ruído protodiastólico curto, de alta frequência, é também auscultado no foco mitral, mas não se observa reforço do ruflar diastólico. Há anicardiosfigmia. Não é detectada turgência jugular a 45°. Estertores crepitantes finos são auscultados em bases. Não há congestão hepática, nem edema de MMII. Exames complementares iniciais (incluindo VHS) revelam-se normais, sendo a pesquisa de ASLO e swab de orofaringe negativos para infecção por Streptococcus pyogenes. Eletrocardiograma revela ritmo de fibrilação atrial, com QT normal. Diante dos dados relatados, a melhor explicação para o quadro da paciente é",
