    "clinicalCase": "No atendimento de urgências por queimaduras, a avaliação da extensão da superfície corporal queimada (SCQ) do paciente pode ser feita pela “regra dos nove\", diagrama de Lund e Browder e, mais recentemente, com uso de aplicativos em smartphones. Utilizando a regra dos nove em um paciente masculino de 60 anos, pesando 50 Kg, com queimadura de 3.o grau que atinge a totalidade do membro superior direito e a totalidade do membro inferior esquerdo, tem-se, respectivamente, a superfície corporal estimada e a reposição hídrica, segundo a fórmula de Parkland, de",
