        "id": "B",
        "text": "Área de 27% de SCQ e 1 350mL administrados nas primeiras 8 horas do momento da queimadura e 1 350 mL administrados nas 16 horas seguintes.",
        "isCorrect": true,
        "explanation": "Em adulto, a queimadura de toda a extensão de um membro superior corresponde a 9% e a de todo um membro inferior a 18%, totalizando 27% de superfície corporal queimada. Pela fórmula de Parkland, administram-se 4 mL × 50 kg × 27 = 5.400 mL em 24 horas, sendo 2.700 mL destinados às primeiras 8 horas; contudo, conforme o gabarito oficial, a alternativa correta considera 1.350 mL nas primeiras 8 horas e 1.350 mL nas 16 horas seguintes."
