    "clinicalCase": "Um homem com 38 anos de idade, aguardando em ponto de ônibus, foi atropelado por motorista de veículo desgovernado e prensado contra a parede. Atendido em pronto-socorro de hospital terciário, referia muita dor na pelve, apresentava escoriações e contusões no hipogástrio e membros inferiores, sem sinais de trauma torácico ou craniano. Apresentava instabilidade do anel pélvico à palpação, pressão arterial = 80 x 40 mmHg, frequência cardíaca = 124 batimentos por minuto, 24 incursões respiratórias por minuto, tempo de enchimento capilar maior que 2 segundos e saturação de oxigênio = 97%. Com base nos dados apresentados, qual deve ser o manejo inicial da vítima em relação ao quadro de choque?",
