    "clinicalCase": "Uma mulher de 27 anos de idade, de etnia afrodescendente, retorna ao ambulatório de clínica médica para mostrar os resultados dos exames complementares solicitados na última consulta. A paciente havia sido atendida em função de sintomas constitucionais (febre intermitente, mal-estar, anorexia, desânimo e artralgias) e importante queda de cabelos. Ao exame físico, havia sido observada a presença de sinovite em punhos, cotovelos, joelhos e tornozelos. Além de padrão de alopecia generalizada (eflúvio telógeno). Havia histórico familiar de artrite reumatoide, lupus eritematoso e tireoidite de Hashimoto. A paciente negava tabagismo e etilismo, referindo apenas uso regular de contraceptivo hormonal oral. Os resultados dos exames complementares solicitados à ocasião da 1.a consulta revelaram: hemoglobina = 10,2 g/dL (valor de referência: 12 a 15,5 g/dL); contagem de plaquetas = 102 000/mm3 (valor de referência: 150 000 a 400 000/mm3); leucograma (incluindo diferencial) normal; TSH = 8 UI/ml (valor de referência: 0,5 a 5,0 UI/ml); T4 livre = 1,2 ng/dL (valor de referência: 0,9 a 1,9 ng/dL); FAN = presente em título 1:640 (valor de referência < 1:80), padrão periférico; anti-DNAds: presente em título 1:240 (valor de referência < 1:100); C3: 33 mg/dL (valor de referência: 90 a 180 mg/dl); VDRL + 1:4 (valor de referência: negativo); IgG anticardiolipina: 12 GPL (valor de referência < 10 GPL); ureia: 44 mg/dL (valor de referência: 20 a 40 mg/dL); creatinina = 1,2 mg/dL (valor de referência: 0,7 a 1,1 mg/dL); exame de urina tipo I com hematúria microscópica e proteinúria leve a moderada; SPOT urinário com proteinúria estimada de 560 mg (valor de referência < 151 mg). Diante dos dados apresentados, a melhor explicação diagnóstica para o caso é",
